insert into public.exercise_catalog (id,data,published) values
('dumbbell-bench','{"id":"dumbbell-bench","name":"Press de banca con mancuernas","aliases":[],"purpose":"Fuerza de empuje horizontal y control de ambos brazos.","steps":["Apoya pies y espalda en un banco estable. Coloca las mancuernas junto al pecho, muñecas encima de los codos.","Empuja ambas cargas hacia arriba con intención rápida, sin perder los apoyos ni golpear las mancuernas entre sí.","Baja controlando hasta un recorrido cómodo. Termina dejando las repeticiones en reserva indicadas."],"mistake":"Rebotar abajo, levantar los glúteos o forzar el hombro con los codos completamente abiertos.","learn":"Haz aproximaciones progresivas. Para cargas altas, acuerda ayuda para colocar y retirar las mancuernas.","image":{"src":"/training/combat-strength.png","tile":0,"columns":4,"rows":2},"version":1}'::jsonb,true),
('pull-up','{"id":"pull-up","name":"Dominadas estrictas","aliases":[],"purpose":"Fuerza de tracción vertical para complementar los empujes.","steps":["Usa una barra fija y agarre cómodo algo más ancho que hombros; inicia con el tronco controlado.","Lleva los codos hacia las costillas para subir, sin impulso de piernas ni extender el cuello buscando la barra.","Desciende de forma controlada. Usa asistencia si no puedes completar el rango y las repeticiones en reserva."],"mistake":"Balancearte o añadir lastre antes de dominar las repeticiones estrictas.","learn":"Empieza con asistencia o jalón al pecho; el lastre solo si dominas tu peso corporal.","image":{"src":"/training/combat-strength.png","tile":1,"columns":4,"rows":2},"version":1}'::jsonb,true),
('trap-bar-deadlift','{"id":"trap-bar-deadlift","name":"Peso muerto con barra hexagonal","aliases":[],"purpose":"Fuerza de piernas y cadera con carga centrada alrededor del cuerpo.","steps":["Sitúate dentro de la barra, pies a anchura cómoda. Agarra las asas y ajusta cadera y rodillas con espalda estable.","Tensa el tronco y empuja el suelo; hombros y cadera suben coordinados, brazos largos.","Termina erguido sin echarte atrás y baja controlando hasta el suelo. Recoloca y respira antes de repetir."],"mistake":"Arrancar con tirón, redondear la espalda o terminar hiperextendiendo la zona lumbar.","learn":"Aprende con una carga ligera y asas altas si hace falta. Los kilos se eligen por técnica y reserva, no por el ejemplo de otra persona.","image":{"src":"/training/combat-strength.png","tile":2,"columns":4,"rows":2},"version":1}'::jsonb,true),
('box-jump','{"id":"box-jump","name":"Salto al cajón bajo","aliases":[],"purpose":"Impulso explosivo con aterrizaje estable.","steps":["Usa un cajón bajo, sólido y antideslizante que puedas alcanzar sin recoger excesivamente las rodillas.","Haz una flexión corta de cadera y rodillas y salta con intención rápida; aterriza con ambos pies completos y rodillas alineadas.","Estabiliza, baja caminando un pie cada vez y recolócate. Descansa entre repeticiones; corta si baja la altura o el control."],"mistake":"Usar un cajón demasiado alto, caer en sentadilla profunda o saltar hacia abajo para encadenar rebotes.","learn":"Ensaya primero el aterrizaje a nivel del suelo y usa la altura mínima adecuada.","image":{"src":"/training/combat-strength.png","tile":3,"columns":4,"rows":2},"version":1}'::jsonb,true),
('kettlebell-swing','{"id":"kettlebell-swing","name":"Swing con kettlebell","aliases":[],"purpose":"Extensión rápida de cadera y producción de potencia con carga moderada.","steps":["Coloca la pesa delante, sujétala con ambas manos y llévala entre las piernas mediante una bisagra de cadera.","Extiende la cadera con rapidez y deja que la pesa flote aproximadamente a la altura del pecho, con brazos largos.","Espera a que vuelva hacia ti para llevar la cadera atrás. Mantén columna estable y termina depositando la pesa con control."],"mistake":"Levantar la pesa con los hombros, convertirlo en sentadilla o arquear la espalda arriba.","learn":"Domina primero la bisagra y el peso muerto con kettlebell. No uses una mancuerna improvisada para sustituir el agarre.","image":{"src":"/training/combat-strength.png","tile":4,"columns":4,"rows":2},"version":1}'::jsonb,true),
('landmine-punch','{"id":"landmine-punch","name":"Press rotacional en landmine","aliases":[],"purpose":"Coordinar impulso de piernas, rotación de cadera y empuje diagonal.","steps":["Asegura la barra en un anclaje landmine. Coloca el extremo a la altura del hombro, con pies separados y un pie atrasado.","Empuja el suelo, permite pivotar el pie posterior y acompaña con la cadera mientras extiendes el brazo en diagonal.","Regresa controlando a la posición inicial. Practica ambos lados con carga que puedas acelerar; no fuerces el giro lumbar."],"mistake":"Clavar la barra en una esquina sin anclaje seguro o copiar un golpe lastrado con torsión lumbar.","learn":"Ensaya con barra sin discos. Es preparación física; la guardia y la técnica de golpeo las ajusta tu entrenador.","image":{"src":"/training/combat-strength.png","tile":5,"columns":4,"rows":2},"version":1}'::jsonb,true),
('plate-chop','{"id":"plate-chop","name":"Elevación diagonal con disco","aliases":[],"purpose":"Coordinar transferencia diagonal de fuerza con control del tronco.","steps":["Sujeta un disco ligero con ambas manos cerca de una cadera y coloca los pies separados a una anchura estable.","Eleva en diagonal hacia el hombro contrario acompañando con caderas y pivote de pies; acelera solo si controlas la trayectoria.","Frena y vuelve despacio. Haz ambos lados sin buscar amplitud máxima ni retorcer la zona lumbar."],"mistake":"Elegir demasiado peso, tirar solo de brazos o girar con los pies clavados.","learn":"Primero recorrido lento y carga ligera. Aumenta velocidad sin perder la capacidad de frenar.","image":{"src":"/training/combat-strength.png","tile":6,"columns":4,"rows":2},"version":1}'::jsonb,true),
('russian-twist','{"id":"russian-twist","name":"Giro ruso con pies apoyados","aliases":[],"purpose":"Resistencia del tronco frente a rotación controlada, como accesorio.","steps":["Siéntate con rodillas flexionadas y talones apoyados. Inclina ligeramente el tronco sin redondear la espalda.","Sujeta una carga ligera cerca del pecho y rota suavemente los hombros a un lado manteniendo la pelvis estable.","Vuelve al centro y cambia de lado con control. Respira durante todo el recorrido y limita el giro a un rango cómodo."],"mistake":"Balancear una carga pesada de lado a lado o forzar la espalda en flexión y rotación.","learn":"Empieza sin disco. Si aparece molestia, sustituye por Pallof o plancha lateral.","image":{"src":"/training/combat-strength.png","tile":7,"columns":4,"rows":2},"version":1}'::jsonb,true)
